for n,p in [('DV','/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'),('DVB','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'),('DVI','/usr/share/fonts/truetype/dejavu/DejaVuSans-Oblique.ttf')]: pdfmetrics.registerFont(TTFont(n,p))
NAVY=colors.HexColor('#113E50'); TEAL=colors.HexColor('#17617A'); MID=colors.HexColor('#52636D'); LIGHT=colors.HexColor('#EAF2F6'); LIGHT2=colors.HexColor('#F7F9FA'); LINE=colors.HexColor('#7EA6B8'); TEXT=colors.HexColor('#242C31'); GREEN=colors.HexColor('#356C55')
ss=getSampleStyleSheet(); base=ParagraphStyle('b',parent=ss['BodyText'],fontName='DV',fontSize=10.3,leading=14.2,textColor=TEXT,spaceAfter=4); center=ParagraphStyle('c',parent=base,alignment=TA_CENTER,fontSize=11,leading=15); formula=ParagraphStyle('f',parent=center,fontSize=11.2,leading=17,spaceAfter=5); sec=ParagraphStyle('s',parent=base,fontName='DVB',fontSize=17,leading=21,textColor=NAVY,spaceBefore=7,spaceAfter=4); sub=ParagraphStyle('sub',parent=base,fontName='DVB',fontSize=12.5,leading=16,textColor=TEAL,spaceBefore=6,spaceAfter=3); lab=ParagraphStyle('l',parent=base,fontName='DVB',fontSize=10.1,leading=12.5,textColor=NAVY); ans=ParagraphStyle('a',parent=base,fontName='DVB',textColor=GREEN); t1=ParagraphStyle('t1',parent=base,fontName='DVB',fontSize=14,leading=18,textColor=TEAL,alignment=TA_CENTER,spaceAfter=9); t2=ParagraphStyle('t2',parent=base,fontName='DVB',fontSize=24,leading=29,textColor=NAVY,alignment=TA_CENTER,spaceAfter=7); t3=ParagraphStyle('t3',parent=base,fontName='DVI',fontSize=12,leading=16,textColor=MID,alignment=TA_CENTER,spaceAfter=8)
def P(x,s=base): return Paragraph(x,s)
